{
    "$schema": "http://json-schema.org/draft-07/schema",
    "title": "MUN CS Society Blog Posts",
    "description": "Represents a collection of blog posts",
    "type": "object",
    "properties": {
        "months": {
            "type": "array",
            "description": "Contains a collection of months that blog posts were posted in",
            "items": {
                "type": "object",
                "description": "A month containing blog posts",
                "properties": {
                    "month": {
                        "type": "string",
                        "description": "The string representation of this month"
                    },
                    "posts": {
                        "type": "array",
                        "description": "A collection of the posts written in this month",
                        "items": {
                            "type": "object",
                            "description": "An individual blog post",
                            "properties": {
                                "title": {
                                    "type": "string",
                                    "description": "The title of this blog post"
                                },
                                "author": {
                                    "type": "string",
                                    "description": "The author of this blog post"
                                },
                                "folder": {
                                    "type": "string",
                                    "description": "The name of the folder under the blog folder that contains this post"
                                }
                            },
                            "required": [
                                "title",
                                "author",
                                "folder"
                            ]
                        }
                    }
                },
                "required": [
                    "month",
                    "posts"
                ]
            }
        }
    },
    "required": [
        "months"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "rating_history": {
            "type": "array",
            "items": {
                "type": "integer"
            }
        },
        "score_history": {
            "type": "object",
            "patternProperties": {
                "^\\d+$": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                            "player_id": {
                                "type": "integer"
                            },
                            "score": {
                                "type": "integer"
                            },
                            "rating_delta": {
                                "type": "number"
                            },
                            "place": {
                                "type": "integer"
                            }
                        },
                        "required": [
                            "player_id",
                            "score",
                            "rating_delta",
                            "place"
                        ]
                    }
                }
            }
        },
        "players_info": {
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "id": {
                        "type": "integer"
                    },
                    "display_name": {
                        "type": "string"
                    },
                    "tenhou_id": {
                        "type": "string"
                    }
                },
                "required": [
                    "id",
                    "display_name",
                    "tenhou_id"
                ]
            }
        },
        "places_summary": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "1": {
                    "type": "integer"
                },
                "2": {
                    "type": "integer"
                },
                "3": {
                    "type": "integer"
                },
                "4": {
                    "type": "integer"
                }
            },
            "required": [
                "1",
                "2",
                "3",
                "4"
            ]
        },
        "total_played_games": {
            "type": "integer"
        },
        "total_played_rounds": {
            "type": "integer"
        },
        "win_summary": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "ron": {
                    "type": "integer"
                },
                "tsumo": {
                    "type": "integer"
                },
                "chombo": {
                    "type": "integer"
                },
                "feed": {
                    "type": "integer"
                },
                "tsumofeed": {
                    "type": "integer"
                },
                "openhand": {
                    "type": "integer"
                }
            },
            "required": [
                "ron",
                "tsumo",
                "chombo",
                "feed",
                "tsumofeed"
            ]
        },
        "hands_value_summary": {
            "type": "object",
            "patternProperties": {
                "^-?\\d+$": {
                    "type": "integer"
                }
            }
        },
        "yaku_summary": {
            "type": "object",
            "patternProperties": {
                "^\\d+$": {
                    "type": "integer"
                }
            }
        },
        "riichi_summary": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "riichi_won": {
                    "type": "integer"
                },
                "riichi_lost": {
                    "type": "integer"
                },
                "feed_under_riichi": {
                    "type": "integer"
                }
            },
            "required": [
                "riichi_won",
                "riichi_lost",
                "feed_under_riichi"
            ]
        }
    },
    "additionalProperties": false,
    "required": [
        "rating_history",
        "score_history",
        "players_info",
        "places_summary",
        "total_played_games",
        "total_played_rounds",
        "win_summary",
        "hands_value_summary",
        "yaku_summary",
        "riichi_summary"
    ]
}

{
    "id": "https://almanak.github.io/schemas/base.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Base-skema",
    "description": "Basis-schema for all entity-resources. Do not use on its own. Extended by domain-schemas.",
    "type": "object",
    "_meta": {
        "indexedProperties": [
            "id",
            "domain",
            "schema"
        ],
        "systemProperties": [
            "uuid",
            "id",
            "domain",
            "schema",
            "created",
            "created_by",
            "updated",
            "updated_by"
        ],
        "fulltextProperties": [
            "description"
        ],
        "autocompleteProperties": [
            "label"
        ]
    },
    "properties": {
        "uuid": {
            "type": "string",
            "title": "Universal unique identifier",
            "description": "UUID1. Assigned by system",
            "pattern": "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
        },
        "id": {
            "type": "string",
            "title": "Resourcespecifik ID",
            "description": "9-cifret l\u00f8benummer semi-specifik for resourcetypen. Assigned by system",
            "maxLength": 9,
            "pattern": "^[0-9]{9}$"
        },
        "domain": {
            "type": "string",
            "enum": [
                "records",
                "people",
                "organisations",
                "families",
                "events",
                "places",
                "concepts",
                "things"
            ],
            "title": "Resourcetype"
        },
        "schema": {
            "type": "string",
            "title": "Skema",
            "description": "Hvilket jsonskema bruges til oprettelse, visning, opdatering og validering af denne ressource"
        },
        "created": {
            "type": "string",
            "format": "date-time",
            "title": "Skabt",
            "description": "Datetime for skabelse af metadata-ressourcen"
        },
        "created_by": {
            "type": "string",
            "maxLength": 255,
            "title": "Skabt af",
            "description": "Brugernavn/ID p\u00e5 skaber/oploader af metadata-ressourcen"
        },
        "updated": {
            "type": "string",
            "format": "date-time",
            "title": "Senest opdateret",
            "description": "Datetime for seneste opdatering af ressourcen"
        },
        "updated_by": {
            "type": "string",
            "maxLength": 255,
            "title": "Senest opdateret af",
            "description": "Brugernavn p\u00e5 seneste opdaterer af metadata-ressourcen"
        },
        "status": {
            "type": "string",
            "enum": [
                "validated",
                "machine-generated",
                "user-generated"
            ],
            "title": "Status",
            "default": "user-generated"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "definitions": {
        "subdocument": {
            "type": "object",
            "patternProperties": {
                "^[^$]": {
                    "$ref": "#/definitions/value"
                }
            },
            "additionalProperties": false
        },
        "value": {
            "oneOf": [
                {
                    "type": "string"
                },
                {
                    "type": "number"
                },
                {
                    "type": "boolean"
                },
                {
                    "type": "null"
                },
                {
                    "$ref": "#/definitions/$binary"
                },
                {
                    "$ref": "#/definitions/$date"
                },
                {
                    "$ref": "#/definitions/$oid"
                },
                {
                    "$ref": "#/definitions/$timestamp"
                },
                {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/value"
                    }
                },
                {
                    "$ref": "#/definitions/subdocument"
                }
            ]
        },
        "$binary": {
            "type": "object",
            "properties": {
                "$binary": {
                    "type": "string"
                },
                "$type": {
                    "type": "string",
                    "pattern": "[a-z0-9]"
                }
            },
            "required": [
                "$binary",
                "$type"
            ],
            "additionalProperties": false
        },
        "$date": {
            "type": "object",
            "properties": {
                "$date": {
                    "type": "integer"
                }
            },
            "required": [
                "$date"
            ],
            "additionalProperties": false
        },
        "$oid": {
            "type": "object",
            "properties": {
                "$oid": {
                    "type": "string",
                    "pattern": "^[0-9a-f]{24}$"
                }
            },
            "required": [
                "$oid"
            ],
            "additionalProperties": false
        },
        "$timestamp": {
            "type": "object",
            "properties": {
                "$timestamp": {
                    "type": "object",
                    "properties": {
                        "t": {
                            "type": "integer"
                        },
                        "i": {
                            "type": "integer"
                        }
                    },
                    "required": [
                        "t",
                        "i"
                    ],
                    "additionalProperties": false
                }
            },
            "required": [
                "$timestamp"
            ],
            "additionalProperties": false
        }
    },
    "allOf": [
        {
            "$ref": "#/definitions/subdocument"
        },
        {
            "required": [
                "_id"
            ]
        }
    ]
}
